definition.script:
pipeline {
  agent any

  tools {
    nodejs 'node25'
  }

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15'))
    timeout(time: 30, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/webdevguide.git'
      }
    }
    stage('Frontend') {
      steps {
        dir('frontend') {
          sh '''
            set -e
            npm ci --no-audit --no-fund
            npm run lint --if-present
            npm test --if-present
            NODE_OPTIONS=--max-old-space-size=2048 npm run build
          '''
        }
      }
    }
    stage('Backend') {
      steps {
        dir('backend') {
          sh '''
            set -e
            python3 -m pip install --break-system-packages -q -r requirements.txt
            python3 -m flake8 . || true
            [ -d tests ] && python3 -m pytest -q || echo "no backend tests"
          '''
        }
      }
    }
  }

  post {
    always { cleanWs() }
  }
}
